const data = $input.first().json;
const event = data.event_type;
const emailConfig = data.tenant_config.email;

const templateId = emailConfig.templates[event] || null;

if (!templateId) {
  throw new Error(`No template mapped for event '${event}' on tenant: ${data.tenant_config.tenant_id}`);
}

return [{
  json: {
    ...data,
    email_payload: {
      from_name: emailConfig.from_name,
      recipient: data.payload.customer_email,
      template_id: templateId,
      event_type: event
    }
  }
}];

